/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: savedDraft, mount, names
 *   Constants: help, phraseHelp, labelHelp, messages, noPrimary
 * Tests
 *   - entries render as an ordered list of position-named fields, and the last entry has no join phrase
 *   - Move up by keyboard reorders the entries, keeps focus on the moved entry and announces its new position
 *   - moves across the primary and featured boundary or past either end are unavailable and change nothing
 *   - a role change moves the entry across groups, announces its new role and position, and keeps focus on its role
 *   - editing a join phrase never changes a role, an emptied phrase is none, and a move keeps each phrase in its position
 *   - Add Artist focuses the new entry's name and announces it, and stops at 20 entries with the limit explained
 *   - removing two unnamed entries in turn announces the repeated message again
 *   - Remove announces the removal and moves focus to the next entry, then the previous one, then Add Artist
 *   - an edited list with an empty, repeated, refused or too long name or phrase blocks Save with its message
 *   - an emptied or new name blocks Save at once but is marked only after its field loses focus or a Save attempt
 *   - a draft without a primary entry shows a note that does not block Save
 *   - a saved, unedited list is never checked, so an unrelated edit still saves
 *   - the label field saves a name without an ID, clearing it saves no label, and a refused or too long label blocks Save
 *   - the disabled editor disables every entry control and the label
 *   - renaming an entry and retyping its saved name restores the saved entry exactly, MusicBrainz ID included
 *   - retyping a saved label's name restores its MusicBrainz ID, and a renamed label drops it
 * @end-catalog */

import { useState } from 'react';
import { cleanup, fireEvent, render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import type { ImportArtistEntry, ImportDraftV2 } from './adminApi';
import { ImportDraftV2Editor } from './ImportDraftV2Editor';
import { draftChanges } from './importDraftPatch';
import { artistEntry, detail, entryKey, labelEntry } from './adminFixtures.testSupport';
afterEach(cleanup);

const help = 'Primary Artists come before featured Artists. Use Move up and Move down to reorder within a group, and change a role to move an entry to the other group.';
const phraseHelp = 'Shown between this name and the next one. Leave empty for a comma.', labelHelp = 'An optional record label or other Organization. Leave empty for no label.';
const messages = { required: 'Enter a name, or remove this Artist entry.', duplicate: 'Another Artist entry already has this name (ignoring case).', invalid: 'Remove control or invisible formatting characters from this name.', tooLong: 'Shorten this name to 200 characters.', phrase: 'Use visible text without control or invisible characters, or leave empty for a comma.' };
const noPrimary = 'Publishing a new Album needs at least one primary Artist entry.';

/** A saved draft holding these entries and label. */
function savedDraft(artists: ImportArtistEntry[], label: ImportDraftV2['album']['label'] = null): ImportDraftV2 {
  const draft = detail().draft; draft.album.artists = artists; draft.album.label = label; return draft;
}
/** The editor inside a form like the import page's: Save submits only when native constraint validation passes. */
function mount(saved: ImportDraftV2, disabled = false) {
  const submit = vi.fn(), changes = vi.fn(), state = { draft: saved };
  function Harness() {
    const [draft, setDraft] = useState(saved); state.draft = draft;
    return <form onSubmit={event => { event.preventDefault(); submit(draft); }}>
      <ImportDraftV2Editor draft={draft} saved={saved} filenames={detail().manifest.files} disabled={disabled} onChange={next => { changes(next); setDraft(next); }} />
      <button type="submit">Save</button>
    </form>;
  }
  render(<Harness />);
  return { submit, changes, state, user: userEvent.setup(), save: () => screen.getByRole('button', { name: 'Save' }) };
}
const names = (draft: ImportDraftV2) => draft.album.artists.map(entry => entry.name);

test('entries render as an ordered list of position-named fields, and the last entry has no join phrase', () => {
  mount(savedDraft([{ ...artistEntry('Lorem'), joinPhrase: ' & ' }, artistEntry('Ipsum', entryKey(2), 'featured')]));
  const group = screen.getByRole('group', { name: 'Artists' });
  expect(group).toHaveAccessibleDescription(help); expect(within(within(group).getByRole('list')).getAllByRole('listitem')).toHaveLength(2);
  expect(screen.getByRole('textbox', { name: '1 · Artist name' })).toHaveValue('Lorem'); expect(screen.getByRole('combobox', { name: '1 · Role' })).toHaveValue('primary');
  expect(screen.getByRole('textbox', { name: '1 · Join phrase' })).toHaveValue(' & '); expect(screen.getByRole('textbox', { name: '1 · Join phrase' })).toHaveAccessibleDescription(phraseHelp);
  expect(screen.getByRole('combobox', { name: '2 · Role' })).toHaveValue('featured'); expect(screen.queryByRole('textbox', { name: '2 · Join phrase' })).not.toBeInTheDocument();
  expect(screen.getByText('Byline: Lorem & Ipsum')).toBeVisible();
  expect(screen.getByRole('textbox', { name: 'Label' })).toHaveAccessibleDescription(labelHelp);
  // The shared draft fields stay, including each track's Disc Number; the v1 Artist name field is gone.
  expect(screen.getByRole('spinbutton', { name: '2 · Disc number' })).toBeInTheDocument(); expect(screen.queryByRole('textbox', { name: 'Artist name' })).not.toBeInTheDocument();
});

test('Move up by keyboard reorders the entries, keeps focus on the moved entry and announces its new position', async () => {
  const { user, changes, state } = mount(savedDraft([artistEntry('Lorem'), artistEntry('Ipsum', entryKey(2))]));
  screen.getByRole('button', { name: 'Move up · Ipsum' }).focus();
  await user.keyboard('{Enter}');
  expect(names(state.draft)).toEqual(['Ipsum', 'Lorem']); expect(screen.getByRole('textbox', { name: '1 · Artist name' })).toHaveValue('Ipsum');
  expect(document.activeElement).toBe(screen.getByRole('button', { name: 'Move up · Ipsum' })); expect(document.activeElement).toHaveAttribute('aria-disabled', 'true');
  expect(screen.getByRole('status')).toHaveTextContent('Ipsum moved to position 1 of 2.');
  // At the top the move is unavailable: pressing it again changes nothing.
  await user.keyboard('{Enter}');
  expect(changes).toHaveBeenCalledOnce(); expect(names(state.draft)).toEqual(['Ipsum', 'Lorem']);
  screen.getByRole('button', { name: 'Move down · Ipsum' }).focus(); await user.keyboard('{Enter}');
  expect(names(state.draft)).toEqual(['Lorem', 'Ipsum']); expect(document.activeElement).toBe(screen.getByRole('button', { name: 'Move down · Ipsum' }));
  expect(screen.getByRole('status')).toHaveTextContent('Ipsum moved to position 2 of 2.');
});

test('moves across the primary and featured boundary or past either end are unavailable and change nothing', async () => {
  const { user, changes } = mount(savedDraft([artistEntry('Lorem'), artistEntry('Ipsum', entryKey(2), 'featured')]));
  for (const name of ['Move up · Ipsum', 'Move down · Lorem', 'Move up · Lorem', 'Move down · Ipsum']) {
    const button = screen.getByRole('button', { name }); expect(button).toHaveAttribute('aria-disabled', 'true'); await user.click(button);
  }
  expect(changes).not.toHaveBeenCalled(); expect(screen.getByRole('status')).toBeEmptyDOMElement();
});

test('a role change moves the entry across groups, announces its new role and position, and keeps focus on its role', async () => {
  const { user, state } = mount(savedDraft([artistEntry('Lorem'), artistEntry('Ipsum', entryKey(2)), artistEntry('Dolor', entryKey(3), 'featured')]));
  await user.selectOptions(screen.getByRole('combobox', { name: '1 · Role' }), 'featured');
  expect(state.draft.album.artists.map(entry => [entry.name, entry.role])).toEqual([['Ipsum', 'primary'], ['Lorem', 'featured'], ['Dolor', 'featured']]);
  expect(screen.getByRole('status')).toHaveTextContent('Lorem is now Featured, at position 2 of 3.');
  expect(document.activeElement).toBe(screen.getByRole('combobox', { name: '2 · Role' }));
  await user.selectOptions(screen.getByRole('combobox', { name: '3 · Role' }), 'primary');
  expect(names(state.draft)).toEqual(['Ipsum', 'Dolor', 'Lorem']); expect(screen.getByRole('status')).toHaveTextContent('Dolor is now Primary, at position 2 of 3.');
  expect(document.activeElement).toBe(screen.getByRole('combobox', { name: '2 · Role' })); expect(document.activeElement).toHaveValue('primary');
});

test('editing a join phrase never changes a role, an emptied phrase is none, and a move keeps each phrase in its position', async () => {
  const { user, state } = mount(savedDraft([artistEntry('Lorem'), artistEntry('Ipsum', entryKey(2), 'featured'), artistEntry('Dolor', entryKey(3), 'featured')]));
  await user.type(screen.getByRole('textbox', { name: '2 · Join phrase' }), ' feat. ');
  await user.type(screen.getByRole('textbox', { name: '1 · Join phrase' }), ' & ');
  expect(state.draft.album.artists).toEqual([{ ...artistEntry('Lorem'), joinPhrase: ' & ' }, { ...artistEntry('Ipsum', entryKey(2), 'featured'), joinPhrase: ' feat. ' }, artistEntry('Dolor', entryKey(3), 'featured')]);
  expect(screen.getByText('Byline: Lorem & Ipsum feat. Dolor')).toBeVisible();
  await user.click(screen.getByRole('button', { name: 'Move down · Ipsum' }));
  expect(state.draft.album.artists.map(entry => [entry.name, entry.joinPhrase])).toEqual([['Lorem', ' & '], ['Dolor', ' feat. '], ['Ipsum', null]]);
  expect(screen.getByText('Byline: Lorem & Dolor feat. Ipsum')).toBeVisible(); expect(screen.queryByRole('textbox', { name: '3 · Join phrase' })).not.toBeInTheDocument();
  await user.clear(screen.getByRole('textbox', { name: '1 · Join phrase' })); expect(state.draft.album.artists[0].joinPhrase).toBeNull();
});

test('Add Artist focuses the new entry\'s name and announces it, and stops at 20 entries with the limit explained', async () => {
  const first = mount(savedDraft([artistEntry('Lorem'), artistEntry('Ipsum', entryKey(2), 'featured')]));
  await first.user.click(screen.getByRole('button', { name: 'Add Artist' }));
  expect(first.state.draft.album.artists.map(entry => [entry.name, entry.role])).toEqual([['Lorem', 'primary'], ['', 'primary'], ['Ipsum', 'featured']]);
  expect(document.activeElement).toBe(screen.getByRole('textbox', { name: '2 · Artist name' })); expect(screen.getByRole('status')).toHaveTextContent('Artist 2 added.');
  expect(screen.getByRole('button', { name: 'Remove · Artist 2' })).toBeInTheDocument();
  cleanup();
  const full = mount(savedDraft(Array.from({ length: 19 }, (_, index) => artistEntry(`Name ${index + 1}`, entryKey(index + 1)))));
  expect(screen.queryByText('An import can have at most 20 Artist entries.')).not.toBeInTheDocument();
  await full.user.click(screen.getByRole('button', { name: 'Add Artist' }));
  expect(full.state.draft.album.artists).toHaveLength(20); expect(document.activeElement).toBe(screen.getByRole('textbox', { name: '20 · Artist name' }));
  expect(screen.getByRole('button', { name: 'Add Artist' })).toBeDisabled();
  expect(screen.getByRole('button', { name: 'Add Artist' })).toHaveAccessibleDescription('An import can have at most 20 Artist entries.');
});

test('removing two unnamed entries in turn announces the repeated message again', async () => {
  const { user } = mount(savedDraft([artistEntry('Lorem'), artistEntry('', entryKey(2)), artistEntry('', entryKey(3))]));
  const status = screen.getByRole('status');
  await user.click(screen.getByRole('button', { name: 'Remove · Artist 2' }));
  const first = within(status).getByText('Artist 2 removed.');
  await user.click(screen.getByRole('button', { name: 'Remove · Artist 2' }));
  // The same text arrives in a new node, so the live region changes and a screen reader speaks it again.
  const second = within(status).getByText('Artist 2 removed.');
  expect(second).not.toBe(first); expect(first).not.toBeInTheDocument(); expect(status.childNodes).toHaveLength(1);
});

test('Remove announces the removal and moves focus to the next entry, then the previous one, then Add Artist', async () => {
  const { user, state } = mount(savedDraft([artistEntry('Lorem'), artistEntry('Ipsum', entryKey(2)), artistEntry('Dolor', entryKey(3))]));
  await user.click(screen.getByRole('button', { name: 'Remove · Lorem' }));
  expect(screen.getByRole('status')).toHaveTextContent('Lorem removed.'); expect(document.activeElement).toBe(screen.getByRole('textbox', { name: '1 · Artist name' })); expect(document.activeElement).toHaveValue('Ipsum');
  await user.click(screen.getByRole('button', { name: 'Remove · Dolor' }));
  expect(screen.getByRole('status')).toHaveTextContent('Dolor removed.'); expect(document.activeElement).toHaveValue('Ipsum');
  await user.click(screen.getByRole('button', { name: 'Remove · Ipsum' }));
  expect(document.activeElement).toBe(screen.getByRole('button', { name: 'Add Artist' })); expect(screen.getByText('No Artist entries yet.')).toBeVisible();
  expect(state.draft.album.artists).toEqual([]);
});

test('an edited list with an empty, repeated, refused or too long name or phrase blocks Save with its message', async () => {
  const { user, submit, save } = mount(savedDraft([artistEntry('Lorem'), artistEntry('Ipsum', entryKey(2))]));
  const name = () => screen.getByRole<HTMLInputElement>('textbox', { name: '2 · Artist name' }), first = () => screen.getByRole<HTMLInputElement>('textbox', { name: '1 · Artist name' });
  for (const [value, message] of [['  ', messages.required], ['LOREM', messages.duplicate], ['Bad\u200BName', messages.invalid], ['Bell\u0007', messages.invalid], ['\u0958'.repeat(101), messages.tooLong]]) {
    fireEvent.change(name(), { target: { value } });
    await user.click(save());
    expect(submit).not.toHaveBeenCalled(); expect(name()).toHaveAttribute('aria-invalid', 'true');
    expect(name()).toHaveAccessibleDescription(message); expect(name().validationMessage).toBe(message);
  }
  // Both entries sharing a name are marked, including the one that was not edited.
  fireEvent.change(name(), { target: { value: 'LOREM' } });
  expect(first()).toHaveAttribute('aria-invalid', 'true'); expect(first()).toHaveAccessibleDescription(messages.duplicate); expect(first().validationMessage).toBe(messages.duplicate);
  fireEvent.change(name(), { target: { value: 'Ipsum' } }); expect(name()).not.toHaveAttribute('aria-invalid'); expect(name().validationMessage).toBe('');
  expect(first()).not.toHaveAttribute('aria-invalid'); expect(first().validationMessage).toBe('');
  const phrase = screen.getByRole<HTMLInputElement>('textbox', { name: '1 · Join phrase' });
  fireEvent.change(phrase, { target: { value: 'a\u200Bb' } });
  await user.click(save());
  expect(submit).not.toHaveBeenCalled(); expect(phrase).toHaveAttribute('aria-invalid', 'true');
  expect(phrase).toHaveAccessibleDescription(`${phraseHelp} ${messages.phrase}`); expect(phrase.validationMessage).toBe(messages.phrase);
  fireEvent.change(phrase, { target: { value: ' & ' } });
  await user.click(save()); expect(submit).toHaveBeenCalledOnce();
});

test('an emptied or new name blocks Save at once but is marked only after its field loses focus or a Save attempt', async () => {
  const { user, submit, save } = mount(savedDraft([artistEntry('Lorem')]));
  await user.click(screen.getByRole('button', { name: 'Add Artist' }));
  const added = screen.getByRole<HTMLInputElement>('textbox', { name: '2 · Artist name' });
  // Taking focus, the new entry is not announced as invalid, yet it would already stop a Save.
  expect(document.activeElement).toBe(added); expect(added).not.toHaveAttribute('aria-invalid'); expect(added).not.toHaveAccessibleDescription(); expect(added.validationMessage).toBe(messages.required);
  await user.tab();
  expect(added).toHaveAttribute('aria-invalid', 'true'); expect(added).toHaveAccessibleDescription(messages.required);
  const name = screen.getByRole<HTMLInputElement>('textbox', { name: '1 · Artist name' });
  fireEvent.change(name, { target: { value: '' } }); expect(name).not.toHaveAttribute('aria-invalid'); expect(name.validationMessage).toBe(messages.required);
  await user.click(save());
  expect(submit).not.toHaveBeenCalled(); expect(name).toHaveAttribute('aria-invalid', 'true'); expect(name).toHaveAccessibleDescription(messages.required);
});

test('a draft without a primary entry shows a note that does not block Save', async () => {
  const { user, submit, save } = mount(savedDraft([artistEntry('Lorem'), artistEntry('Ipsum', entryKey(2), 'featured')]));
  expect(screen.queryByText(noPrimary)).not.toBeInTheDocument();
  await user.selectOptions(screen.getByRole('combobox', { name: '1 · Role' }), 'featured');
  expect(screen.getByText(noPrimary)).toBeVisible(); expect(screen.getByRole('group', { name: 'Artists' })).toHaveAccessibleDescription(`${help} ${noPrimary}`);
  await user.click(save()); expect(submit).toHaveBeenCalledOnce();
  await user.selectOptions(screen.getByRole('combobox', { name: '2 · Role' }), 'primary');
  expect(screen.queryByText(noPrimary)).not.toBeInTheDocument(); expect(screen.getByRole('group', { name: 'Artists' })).toHaveAccessibleDescription(help);
});

test('a saved, unedited list is never checked, so an unrelated edit still saves', async () => {
  const { user, submit, save } = mount(savedDraft([artistEntry('Bad\u200BName'), artistEntry('BAD\u200BNAME', entryKey(2))]));
  expect(screen.getByRole('textbox', { name: '1 · Artist name' })).not.toHaveAttribute('aria-invalid'); expect(screen.getByRole('textbox', { name: '2 · Artist name' })).not.toHaveAttribute('aria-invalid');
  await user.type(screen.getByRole('textbox', { name: 'Title' }), 'Lorem Album');
  await user.click(save()); expect(submit).toHaveBeenCalledOnce();
});

test('the label field saves a name without an ID, clearing it saves no label, and a refused or too long label blocks Save', async () => {
  const { user, submit, save, state } = mount(savedDraft([artistEntry('Lorem')]));
  const label = screen.getByRole<HTMLInputElement>('textbox', { name: 'Label' });
  await user.type(label, 'Lorem Records'); expect(state.draft.album.label).toEqual(labelEntry('Lorem Records'));
  await user.clear(label); expect(state.draft.album.label).toBeNull();
  fireEvent.change(label, { target: { value: 'Lorem\u200B' } });
  await user.click(save());
  expect(submit).not.toHaveBeenCalled(); expect(label).toHaveAttribute('aria-invalid', 'true');
  expect(label).toHaveAccessibleDescription(`${labelHelp} ${messages.invalid}`); expect(label.validationMessage).toBe(messages.invalid);
  fireEvent.change(label, { target: { value: '\u0958'.repeat(101) } });
  await user.click(save());
  expect(submit).not.toHaveBeenCalled(); expect(label).toHaveAccessibleDescription(`${labelHelp} ${messages.tooLong}`); expect(label.validationMessage).toBe(messages.tooLong);
  fireEvent.change(label, { target: { value: 'Lorem Records' } });
  await user.click(save()); expect(submit).toHaveBeenCalledExactlyOnceWith(expect.objectContaining({ album: expect.objectContaining({ label: labelEntry('Lorem Records') }) }));
});

test('the disabled editor disables every entry control and the label', () => {
  mount(savedDraft([artistEntry('Lorem'), artistEntry('Ipsum', entryKey(2))]), true);
  const group = screen.getByRole('group', { name: 'Artists' });
  for (const control of [...within(group).getAllByRole('textbox'), ...within(group).getAllByRole('combobox'), ...within(group).getAllByRole('button')]) expect(control).toBeDisabled();
  expect(screen.getByRole('textbox', { name: 'Label' })).toBeDisabled();
});

test('renaming an entry and retyping its saved name restores the saved entry exactly, MusicBrainz ID included', async () => {
  const entry = { ...artistEntry('Lorem'), joinPhrase: ' & ', musicBrainzId: '30000000-0000-4000-9000-000000000003' }, saved = savedDraft([entry, artistEntry('Ipsum', entryKey(2), 'featured')]);
  const { user, state } = mount(saved);
  const name = screen.getByRole('textbox', { name: '1 · Artist name' });
  await user.clear(name); expect(state.draft.album.artists[0]).toEqual({ ...entry, name: '', musicBrainzId: null });
  await user.type(name, 'Dolor'); expect(state.draft.album.artists[0]).toEqual({ ...entry, name: 'Dolor', musicBrainzId: null });
  await user.clear(name); await user.type(name, 'Lorem');
  expect(state.draft.album.artists[0]).toEqual(entry); expect(draftChanges(saved, state.draft)).toEqual([]);
});

test('retyping a saved label\'s name restores its MusicBrainz ID, and a renamed label drops it', async () => {
  const label = { name: 'Lorem Records', musicBrainzId: '30000000-0000-4000-9000-000000000004' }, saved = savedDraft([artistEntry('Lorem')], label);
  const { user, state } = mount(saved);
  const field = screen.getByRole('textbox', { name: 'Label' });
  expect(field).toHaveValue('Lorem Records');
  await user.clear(field); expect(state.draft.album.label).toBeNull();
  await user.type(field, 'Ipsum Records'); expect(state.draft.album.label).toEqual(labelEntry('Ipsum Records'));
  // Case alone does not rename the label, so its ID comes back; the exact saved name restores the saved label.
  await user.clear(field); await user.type(field, 'LOREM RECORDS'); expect(state.draft.album.label).toEqual({ ...label, name: 'LOREM RECORDS' });
  await user.clear(field); await user.type(field, 'Lorem Records');
  expect(state.draft.album.label).toEqual(label); expect(draftChanges(saved, state.draft)).toEqual([]);
});
